std::vector<std::vector<std::size_t>> boundary_cycles;
for (auto facet = poly.facets_begin(); facet != poly.facets_end(); ++facet) {
    if (facet->is_border()) {
        std::vector<std::size_t> cycle;
        auto halfedge = facet->halfedge();
        do {
            cycle.push_back(halfedge->vertex()->id());
            halfedge = halfedge->next();
        } while (halfedge != facet->halfedge());
        boundary_cycles.push_back(cycle);
    }
}

for (auto& cycle : boundary_cycles) {
    if (cycle.size() < 3) continue;
    std::size_t first = cycle[0];
    for (std::size_t i = 1; i < cycle.size() - 1; ++i) {
        poly.create_facet(first, cycle[i], cycle[i + 1]);
    }
}

